mapper.sql:
owner_user_id=#{ownerUserId} and draft_status='ACTIVE'
and process_name like concat('%', #{processName}, '%') escape '\\'
and update_time >= #{updatedAfter}
and update_time <= #{updatedBefore}

mapper.select:
select  from wf_process_draft
where 
order by update_time desc, draft_id desc limit #{offset}, #{limit}

mapper.update:
update wf_process_draft set form_values=#{formValues},
    multi_instance_user_ids=#{multiInstanceUserIds}, business_key=#{businessKey},
    revision_no=revision_no+1, update_time=current_timestamp(3)
where draft_id=#{draftId} and owner_user_id=#{ownerUserId}
  and draft_status='ACTIVE' and revision_no=#{expectedRevision}

update wf_process_draft set draft_status='DELETED', revision_no=revision_no+1,
    deleted_time=current_timestamp(3), update_time=current_timestamp(3)
where draft_id=#{draftId} and owner_user_id=#{ownerUserId}
  and draft_status='ACTIVE' and revision_no=#{expectedRevision}

update wf_process_draft set draft_status='SUBMITTED', revision_no=revision_no+1,
    submitted_process_instance_id=#{processInstanceId}, submitted_time=current_timestamp(3),
    form_values=#{formValues}, multi_instance_user_ids=#{multiInstanceUserIds},
    business_key=#{businessKey}, update_time=current_timestamp(3)
where draft_id=#{draftId} and owner_user_id=#{ownerUserId}
  and draft_status='ACTIVE' and revision_no=#{expectedRevision}
